/**
 * Set the physics API instance for teleportBody to use.
 *
 * @param {Object} api - Physics instance with .api property for worker calls.
 */
export function setPhysicApi(api: any): void;
/**
 * Clear the physics API reference.
 * Call this on Physics.dispose() to prevent memory leaks across HMR reloads.
 */
export function clearPhysicApiRef(): void;
/**
 * Teleport a body to a world position (and optional rotation).
 *
 * @param {number[]} position - [x, y, z] world position.
 * @param {number[]} [quaternion] - Optional [x, y, z, w] rotation.
 * @param {number} [bodyIndex=0] - Dynamic body index (default: player at 0).
 */
export function teleportBody(position: number[], quaternion?: number[], bodyIndex?: number): void;
